// n8n Code node: "Validate & Clean Lead"  (mode: Run Once for Each Item)
// Takes the raw webhook body, cleans it up, and marks whether it's usable.
const b = $json.body ?? $json;                       // Webhook puts the form data in .body
const message = String(b.message ?? '').trim();

// Turn any US phone format into (305) 555-1234; blank if it isn't 10 digits.
let digits = String(b.phone ?? '').replace(/\D/g, '');
if (digits.length === 11 && digits.startsWith('1')) digits = digits.slice(1);
const phone = digits.length === 10 ? `(${digits.slice(0, 3)}) ${digits.slice(3, 6)}-${digits.slice(6)}` : '';

return {
  json: {
    valid: message.length > 0,                       // a blank message can't be triaged
    lead: {
      id: b.id || `lead-${Date.now()}`,
      name: String(b.name ?? '').trim(),
      phone,
      email: b.email || '',
      address: b.address || '',
      message,
      source: b.source || 'webhook',
      // Schedule clock: the lead's arrival time, or "now" when the form didn't send one.
      // The reply node turns this instant into a window in America/New_York.
      receivedAt: b.receivedAt || new Date().toISOString(),
    },
  },
};

// n8n Code node: "Check AI Answer (fallback + safety guardrail)"  (mode: Run Once for Each Item)
// 1) Use the AI's JSON if it passes validation.  2) Otherwise fall back to keyword rules.
// 3) Gas / CO words ALWAYS force an emergency, whatever the AI said.
const lead = $('Validate & Clean Lead').item.json.lead;
const text = lead.message.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

const URGENCIES = ['emergency', 'urgent', 'routine'];
const JOB_TYPES = ['no_heat', 'no_cooling', 'gas_or_co_safety', 'water_leak', 'noise_or_smell', 'thermostat', 'maintenance', 'install_quote', 'other'];
const GAS = ['gas smell', 'smell gas', 'smells like gas', 'olor a gas', 'huele a gas', 'carbon monoxide', 'co alarm', 'co detector', 'monoxido'];

function rules() {
  const RULES = [
    ['gas_or_co_safety', GAS],
    ['no_heat', ['no heat', 'not heating', 'blowing cold', 'sin calefaccion', 'no hay calefaccion', 'no calienta']],
    ['no_cooling', ['no ac', 'ac not', 'not cooling', 'blowing warm', 'blowing hot', 'sin aire', 'no enfria', 'aire no']],
    ['water_leak', ['leak', 'dripping', 'flood', 'gotea', 'fuga de agua']],
    ['noise_or_smell', ['noise', 'loud', 'banging', 'squeal', 'rattle', 'burning smell', 'ruido']],
    ['thermostat', ['thermostat', 'termostato']],
    ['maintenance', ['tune-up', 'tune up', 'maintenance', 'checkup', 'clean', 'filter', 'mantenimiento', 'limpieza']],
    ['install_quote', ['quote', 'estimate', 'new system', 'replace', 'install', 'heat pump', 'cotizacion', 'presupuesto']],
  ];
  const hit = RULES.find(([, words]) => words.some((w) => text.includes(w)));
  const jobType = hit ? hit[0] : 'other';
  const vulnerable = ['baby', 'elderly', 'grandma', 'oxygen', 'medical', 'bebe', 'abuela', 'anciano'].some((w) => text.includes(w));
  let urgency = 'routine';
  if (jobType === 'gas_or_co_safety') urgency = 'emergency';
  else if (jobType === 'no_heat' || jobType === 'no_cooling') urgency = vulnerable ? 'emergency' : 'urgent';
  else if (jobType === 'water_leak') urgency = 'urgent';
  const es = ['hola', 'por favor', 'gracias', 'no hay', 'aire', 'necesito', 'funciona', 'mi casa'].filter((w) => text.includes(w)).length >= 2;
  return { urgency, jobType, language: es ? 'es' : 'en', summary: `${urgency.toUpperCase()}: ${jobType.replace(/_/g, ' ')}${vulnerable ? ' — vulnerable person in home' : ''}`, confidence: hit ? 0.75 : 0.3 };
}

let triage;
let classifiedBy;
try {
  // If the AI node is deactivated, its input passes straight through (no "choices") — that's normal rules mode.
  if (!$json.choices && $json.valid !== undefined) throw new Error('AI node off');
  const ai = JSON.parse($json.choices[0].message.content);
  if (!URGENCIES.includes(ai.urgency) || !JOB_TYPES.includes(ai.jobType) || !['en', 'es'].includes(ai.language)) {
    throw new Error('AI answer failed validation');
  }
  triage = { ...ai, confidence: Math.min(1, Math.max(0, Number(ai.confidence) || 0.5)) };
  classifiedBy = 'llm';
} catch (err) {
  triage = rules();
  classifiedBy = err.message === 'AI node off' ? 'rules' : 'rules-fallback';
}

// SAFETY GUARDRAIL
if (GAS.some((w) => text.includes(w))) {
  triage.urgency = 'emergency';
  triage.jobType = 'gas_or_co_safety';
}

return { json: { lead, triage: { ...triage, classifiedBy } } };

// Generated by n8n/build-workflow.mjs from src/schedule-core.js and n8n/code/3-build-reply.body.js.
// Edit those files, then run: node n8n/build-workflow.mjs
// schedule-core.js — the only copy of the time-window rules.
// n8n/build-workflow.mjs pastes this file into the n8n Code node so the
// workflow cannot drift from the CLI.
//
// Dates are civil days in America/New_York (the shop is in Homestead, FL).
// Date#getDay / setDate / getHours and toLocaleDateString() follow the host
// timezone, so a UTC server and an Eastern laptop can disagree on the calendar
// day and on the 2pm cutoff. A missing receivedAt also schedules from "now":
// the Nov 7 demo (Saturday 9:58 AM ET, no receivedAt) was Tue Nov 10–Fri Nov 13,
// while the sample file's Monday Nov 9 arrival time is Wed Nov 11–Mon Nov 16.

const SHOP_TIME_ZONE = "America/New_York";

/** Year/month/day/hour of an instant on the shop's wall clock. */
function shopWallClock(instant) {
  const fmt = new Intl.DateTimeFormat("en-US", {
    timeZone: SHOP_TIME_ZONE,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    hourCycle: "h23",
  });
  const parts = {};
  for (const part of fmt.formatToParts(instant)) {
    if (part.type !== "literal") parts[part.type] = part.value;
  }
  let hour = Number(parts.hour);
  if (hour === 24) hour = 0; // some ICU builds report midnight as 24
  return {
    year: Number(parts.year),
    month: Number(parts.month),
    day: Number(parts.day),
    hour,
    minute: Number(parts.minute),
  };
}

/**
 * Which clock a lead is scheduled from.
 * An explicit `now` (tests) wins, then the lead's receivedAt, then the current time.
 */
function scheduleInstant(lead, now) {
  if (now instanceof Date && !Number.isNaN(now.getTime())) return now;
  if (lead && lead.receivedAt) {
    const received = new Date(lead.receivedAt);
    if (!Number.isNaN(received.getTime())) return received;
  }
  return new Date();
}

/** Move a shop calendar date forward by `days` weekdays (Sat/Sun skipped). */
function addBusinessDays(from, days) {
  const start = from instanceof Date ? shopWallClock(from) : from;
  let year = start.year;
  let month = start.month;
  let day = start.day;
  let added = 0;
  while (added < days) {
    const next = new Date(Date.UTC(year, month - 1, day + 1));
    year = next.getUTCFullYear();
    month = next.getUTCMonth() + 1;
    day = next.getUTCDate();
    const weekday = next.getUTCDay();
    if (weekday !== 0 && weekday !== 6) added++;
  }
  return { year, month, day };
}

function formatShopDate(civil) {
  const noonUtc = new Date(Date.UTC(civil.year, civil.month - 1, civil.day, 12));
  return new Intl.DateTimeFormat("en-US", {
    weekday: "short",
    month: "short",
    day: "numeric",
    timeZone: "UTC",
  }).format(noonUtc);
}

function estimateTimeWindow(urgency, now = new Date()) {
  const wall = shopWallClock(now);
  if (urgency === "emergency") {
    return "Today \u2014 on-call tech dispatched, arrival within 2-4 hours";
  }
  if (urgency === "urgent") {
    // Before 2pm shop time we can usually still fit it in today.
    return wall.hour < 14
      ? "Today \u2014 afternoon slot (12pm-6pm)"
      : "Tomorrow \u2014 first morning slot (8am-11am)";
  }
  // Routine work goes 2-5 business days out, skipping the weekend.
  const start = formatShopDate(addBusinessDays(wall, 2));
  const end = formatShopDate(addBusinessDays(wall, 5));
  return `${start} - ${end} \u2014 office will offer a 2-hour arrival window`;
}

/** Spanish wording for the English windows estimateTimeWindow() returns. */
function translateWindow(when) {
  return when
    .replace("Today \u2014 on-call tech dispatched, arrival within 2-4 hours", "hoy, llegada en 2-4 horas")
    .replace("Today \u2014 afternoon slot (12pm-6pm)", "hoy en la tarde (12pm-6pm)")
    .replace("Tomorrow \u2014 first morning slot (8am-11am)", "ma\u00f1ana temprano (8am-11am)")
    .replace("\u2014 office will offer a 2-hour arrival window", "(le daremos una ventana de llegada de 2 horas)");
}
// n8n Code node: "Time Window, Review Checks & Reply Draft"  (mode: Run Once for Each Item)
// estimateTimeWindow, scheduleInstant, and translateWindow are prepended from src/schedule-core.js.
const { lead, triage } = $json;
const BUSINESS = 'Homestead Comfort HVAC';   // <- change to the real company name
const PHONE = '(305) 555-0142';              // <- and phone number
const now = scheduleInstant(lead);
const es = triage.language === 'es';
const timeWindow = estimateTimeWindow(triage.urgency, now);
const spoken = es ? translateWindow(timeWindow) : timeWindow;
const inline = spoken.charAt(0).toLowerCase() + spoken.slice(1);

// --- When should a person check before anything goes out? ---
const reviewReasons = [];
if (triage.confidence < 0.6) reviewReasons.push('low AI confidence');
if (!lead.phone && !lead.email) reviewReasons.push('no way to contact customer');
if (!lead.address && triage.urgency !== 'routine') reviewReasons.push('no address for a dispatch');
if (triage.classifiedBy === 'rules-fallback') reviewReasons.push('AI was down, rules were used');
if (triage.jobType === 'install_quote') reviewReasons.push('sales lead — owner sets the quote');

// --- Reply draft (NOT sent automatically) ---
const name = lead.name.split(' ')[0] || (es ? 'cliente' : 'there');
let replyDraft;
if (triage.jobType === 'gas_or_co_safety') {
  replyDraft = es
    ? `Hola ${name}, le habla ${BUSINESS}. Si huele a gas o su alarma de monóxido suena, salga de la casa ahora y llame al 911 o a la compañía de gas desde afuera. Nuestro técnico llegará en 2-4 horas. ${PHONE}`
    : `Hi ${name}, this is ${BUSINESS}. If you smell gas or your CO alarm is going off, leave the house now and call 911 or your gas company from outside. Our on-call tech is arriving within 2-4 hours. ${PHONE}`;
} else if (triage.urgency === 'emergency') {
  replyDraft = es
    ? `Hola ${name}, le habla ${BUSINESS}. Tratamos su caso como emergencia: nuestro técnico llegará en 2-4 horas. Preguntas: ${PHONE}.`
    : `Hi ${name}, this is ${BUSINESS}. We're treating this as an emergency — our on-call tech is arriving within 2-4 hours. Questions? ${PHONE}.`;
} else if (triage.urgency === 'urgent') {
  replyDraft = es
    ? `Hola ${name}, gracias por contactar a ${BUSINESS}. Podemos enviarle un técnico ${inline}. Responda SÍ para confirmar.`
    : `Hi ${name}, thanks for contacting ${BUSINESS}. We can get a tech to you ${inline}. Reply YES to lock it in.`;
} else {
  replyDraft = es
    ? `Hola ${name}, ¡gracias por contactar a ${BUSINESS}! Próximas citas: ${spoken}. Responda con el día que le convenga.`
    : `Hi ${name}, thanks for contacting ${BUSINESS}! Our next openings are ${spoken}. Reply with a day that works and we'll book it.`;
}

const icon = triage.urgency === 'emergency' ? '🚨' : triage.urgency === 'urgent' ? '⚠️' : '🗓️';
const techAlert = `${icon} ${triage.summary}\nCustomer: ${lead.name || 'unknown'} | ${lead.phone || 'no phone'} | ${lead.address || 'no address'}\nWindow: ${timeWindow}\nSpeaks: ${es ? 'Spanish' : 'English'}${reviewReasons.length ? ' | NEEDS OFFICE REVIEW: ' + reviewReasons.join('; ') : ''}`;

// Flat row for the Google Sheet "mini CRM" (column names = sheet headers)
return {
  json: {
    lead_id: lead.id, received_at: lead.receivedAt, name: lead.name, phone: lead.phone, email: lead.email, address: lead.address,
    message: lead.message, language: triage.language, urgency: triage.urgency, job_type: triage.jobType, summary: triage.summary,
    time_window: timeWindow, needs_review: reviewReasons.length ? 'YES' : 'no', review_reasons: reviewReasons.join('; '),
    classified_by: triage.classifiedBy, confidence: triage.confidence, reply_draft: replyDraft,
    status: reviewReasons.length ? 'waiting for office review' : 'reply ready to send',
    tech_alert: techAlert,
  },
};
